import {createIcons,GripVertical,ArrowUp,Archive,ArchiveRestore,ArrowDown,ArrowLeft,ArrowRight,ArrowUpRight,BookOpen,Camera,Check,Clock3,ChevronLeft,ChevronRight,ContactRound,Download,Eye,Feather,File,FilePenLine,Folder,Folders,ImageOff,Inbox,Info,KeyRound,Languages,Layers2,ListFilter,LogOut,Mail,MailOpen,MailPlus,Mails,Menu,Paperclip,Pause,Pencil,Play,Plus,RefreshCw,Reply,Save,Search,SearchX,Send,Settings2,ShieldCheck,Sparkles,SquarePen,Star,Trash2,Undo2,Unplug,UserPlus,X} from 'lucide';
const icons={GripVertical,ArrowUp,Archive,ArchiveRestore,ArrowDown,ArrowLeft,ArrowRight,ArrowUpRight,BookOpen,Camera,Check,Clock3,ChevronLeft,ChevronRight,ContactRound,Download,Eye,Feather,File,FilePenLine,Folder,Folders,ImageOff,Inbox,Info,KeyRound,Languages,Layers2,ListFilter,LogOut,Mail,MailOpen,MailPlus,Mails,Menu,Paperclip,Pause,Pencil,Play,Plus,RefreshCw,Reply,Save,Search,SearchX,Send,Settings2,ShieldCheck,Sparkles,SquarePen,Star,Trash2,Undo2,Unplug,UserPlus,X};
import DOMPurify from 'dompurify';
