document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(el){event.preventDefault();event.stopPropagation();if(el.disabled)return;const action=el.dataset.action;el.disabled=true;el.setAttribute('aria-busy','true');try{await handleAction(action,el);}catch(e){error(e);}finally{if(el.isConnected){el.disabled=false;el.removeAttribute('aria-busy');}}return;}if(event.target.closest('input,label,a,select'))return;const row=event.target.closest('[data-open]');if(row)try{await openMail(row.dataset.open);}catch(e){error(e);}});
