let columnDrag=null;
document.addEventListener('input',event=>{const key=event.target.dataset.columnRange;if(!key)return;let layout={...currentMailLayout(),[key]:Number(event.target.value)};if(mobileColumns()&&key!=='gap'){layout.mode='table';const select=$('#mail-column-mode');if(select)select.value='table';}try{layout=persistMailLayout(layout);$('#column-value-'+key).textContent=layout[key]+'px';}catch(e){error(e);}});
document.addEventListener('change',event=>{if(event.target.id==='mail-column-mode')try{persistMailLayout({...currentMailLayout(),mode:event.target.value});}catch(e){error(e);}});
document.addEventListener('pointerdown',event=>{const handle=event.target.closest?.('[data-column-resize]');if(!handle)return;event.preventDefault();event.stopPropagation();columnDrag={handle,key:handle.dataset.columnResize,x:event.clientX,layout:currentMailLayout(),mobile:mobileColumns(),id:event.pointerId};handle.setPointerCapture(event.pointerId);document.body.classList.add('resizing-mail-columns');});
document.addEventListener('pointermove',event=>{const d=columnDrag;if(!d||event.pointerId!==d.id)return;event.preventDefault();applyMailLayout(resizeMailColumn(d.layout,d.key,event.clientX-d.x,d.mobile));},{passive:false});
function finishColumnDrag(event){const d=columnDrag;if(!d||event.pointerId!==d.id)return;columnDrag=null;document.body.classList.remove('resizing-mail-columns');try{if(event.type==='pointercancel'||d.mobile!==mobileColumns()){applyMailLayout(currentMailLayout());return;}persistMailLayout(resizeMailColumn(d.layout,d.key,event.clientX-d.x,d.mobile));}catch(e){error(e);}}
document.addEventListener('pointerup',finishColumnDrag);document.addEventListener('pointercancel',finishColumnDrag);
document.addEventListener('keydown',event=>{const handle=event.target.closest?.('[data-column-resize]');if(!handle||!['ArrowLeft','ArrowRight','Home'].includes(event.key))return;event.preventDefault();const key=handle.dataset.columnResize,layout=currentMailLayout();try{persistMailLayout(event.key==='Home'?{...layout,[key]:defaultMailLayout(mobileColumns())[key]}:resizeMailColumn(layout,key,(event.key==='ArrowLeft'?-1:1)*(event.shiftKey?1:8),mobileColumns()));}catch(e){error(e);}});
document.addEventListener('dblclick',event=>{const handle=event.target.closest?.('[data-column-resize]');if(handle){const key=handle.dataset.columnResize;persistMailLayout({...currentMailLayout(),[key]:defaultMailLayout(mobileColumns())[key]});}});
let previousColumnMode=mobileColumns();window.addEventListener('resize',()=>{const next=mobileColumns();if(next!==previousColumnMode){previousColumnMode=next;applyMailLayout(currentMailLayout());}});

